package com.billiard;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:ledger;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000"})
class LedgerTest {
 @Autowired Business b;@Autowired Commerce c;@Autowired Ledger ledger;
 long user(){return b.jdbc().queryForObject("select id from app_user where username='demo-customer'",Long.class);}
 long admin(){return b.jdbc().queryForObject("select id from app_user where username='admin'",Long.class);}
 long other(){return b.jdbc().queryForObject("select id from app_user where username='other-customer'",Long.class);}
 long item(String key){return b.jdbc().queryForObject("select id from service_item where catalog_key=?",Long.class,key);}
 long id(Map<String,Object> map){return ((Number)map.get("id")).longValue();}
 long open(long uid,long table){return id(b.open(uid,false,table,1,UUID.randomUUID().toString(),"MOCK"));}
 Map<String,Object> book(long play,String key){return c.book(user(),false,item(key),play,UUID.randomUUID().toString());}
 @BeforeEach void clear(){b.jdbc().update("delete from personal_history_hide");b.jdbc().update("delete from service_order");b.jdbc().update("delete from play_order");b.jdbc().update("update billiard_table set status='IDLE',active_order_id=null");b.jdbc().update("update coach_grade set rate=1 where stars=3");b.jdbc().update("update service_item set stock=1,rate=24,enabled=true where catalog_key='peri-tianwang'");if(b.jdbc().queryForObject("select count(*) from app_user where username='other-customer'",Integer.class)==0)b.jdbc().update("insert into app_user(username,role) values('other-customer','CUSTOMER')");}
 @Test void coachesStartImmediatelyButCuesRequireFrontDesk(){long play=open(user(),1);var coach=book(play,"coach-tangtang");assertEquals("ACTIVE",coach.get("status"));assertNotNull(coach.get("started_at"));assertThrows(IllegalArgumentException.class,()->c.action(user(),false,id(coach),"cancel"));c.action(user(),false,id(coach),"finish");assertEquals(new BigDecimal("60.00"),b.row("select amount from service_order where id=?",id(coach)).get("amount"));var cue=book(play,"peri-tianwang");assertEquals("REQUESTED",cue.get("status"));assertNull(cue.get("started_at"));assertThrows(IllegalArgumentException.class,()->c.action(user(),false,id(cue),"start"));c.action(admin(),true,id(cue),"start");assertThrows(IllegalArgumentException.class,()->c.action(user(),false,id(cue),"finish"));}
 @Test void bookingAssociationOwnershipAndIdempotence(){long play=open(user(),1),otherPlay=open(other(),2);assertThrows(IllegalArgumentException.class,()->c.book(user(),false,item("coach-tangtang"),otherPlay,UUID.randomUUID().toString()));assertThrows(IllegalArgumentException.class,()->c.book(user(),false,item("coach-tangtang"),0,UUID.randomUUID().toString()));String key=UUID.randomUUID().toString();var order=c.book(admin(),true,item("coach-tangtang"),play,key);assertEquals(user(),((Number)order.get("user_id")).longValue());assertEquals(id(order),id(c.book(admin(),true,item("coach-tangtang"),play,key)));assertThrows(IllegalArgumentException.class,()->c.book(admin(),true,item("coach-tangtang"),otherPlay,key));assertThrows(IllegalArgumentException.class,()->c.book(user(),false,item("coach-tangtang"),play,key));c.action(user(),false,id(order),"finish");b.finish(user(),false,play);assertEquals(id(order),id(c.book(admin(),true,item("coach-tangtang"),play,key)));assertThrows(IllegalArgumentException.class,()->book(play,"coach-mianmian"));}
 @Test void endingSessionStopsCoachAndWaitsForActualCueReturn(){long play=open(user(),1);var coach=book(play,"coach-tangtang");var activeCue=book(play,"peri-tianwang");var waitingCue=book(play,"peri-gold");c.action(admin(),true,id(activeCue),"start");b.jdbc().update("update service_order set started_at=DATEADD('SECOND',-61,CURRENT_TIMESTAMP) where id=?",id(coach));b.finish(user(),false,play);var bill=ledger.bill(user(),false,play);assertEquals("PENDING_RETURN",bill.get("settlementStatus"));assertEquals(new BigDecimal("60.00"),bill.get("unpaidAmount"));assertEquals(new BigDecimal("38.00"),bill.get("tablePaid"));assertEquals(1,bill.get("pendingCueCount"));assertEquals("CANCELLED",b.row("select status from service_order where id=?",id(waitingCue)).get("status"));assertEquals("ACTIVE",b.row("select status from service_order where id=?",id(activeCue)).get("status"));var original=b.row("select * from service_order where id=?",id(coach));b.finish(user(),false,play);assertEquals(original.get("ended_at"),b.row("select * from service_order where id=?",id(coach)).get("ended_at"));assertThrows(IllegalArgumentException.class,()->ledger.settle(user(),false,play,"MOCK"));c.action(admin(),true,id(activeCue),"finish");bill=ledger.bill(user(),false,play);assertEquals(new BigDecimal("84.00"),bill.get("unpaidAmount"));assertEquals("PAYMENT_PENDING",bill.get("settlementStatus"));var paid=ledger.settle(user(),false,play,"MOCK");assertEquals(new BigDecimal("0.00"),paid.get("unpaidAmount"));assertEquals(new BigDecimal("84.00"),paid.get("serviceTotal"));assertEquals("SETTLED",paid.get("settlementStatus"));var payment=b.row("select * from service_order where id=?",id(coach));assertEquals("MOCK",payment.get("payment_method"));ledger.settle(admin(),true,play,"CASH");assertEquals(payment.get("settled_at"),b.row("select * from service_order where id=?",id(coach)).get("settled_at"));assertEquals("MOCK",b.row("select * from service_order where id=?",id(coach)).get("payment_method"));}
 @Test void hiddenHistoryIsPersonalAtomicAndRetainsAccounting(){long play=open(user(),1);var cancelled=book(play,"peri-tianwang");c.action(user(),false,id(cancelled),"cancel");var active=book(play,"coach-tangtang");assertThrows(IllegalArgumentException.class,()->ledger.hide(user(),"CUE",List.of(id(cancelled),id(active)),false));assertEquals(0,b.jdbc().queryForObject("select count(*) from personal_history_hide",Integer.class));assertThrows(IllegalArgumentException.class,()->ledger.hide(other(),"CUE",List.of(id(cancelled)),false));assertThrows(IllegalArgumentException.class,()->ledger.hide(user(),"PLAY",List.of(play),false));ledger.hide(user(),"CUE",List.of(id(cancelled)),false);assertEquals(1,ledger.services(user(),false).size());assertEquals(2,ledger.services(admin(),true).size());assertEquals(2,b.jdbc().queryForObject("select count(*) from service_order",Integer.class));b.finish(user(),false,play);assertThrows(IllegalArgumentException.class,()->ledger.hide(user(),"PLAY",List.of(play),false));assertEquals(0,ledger.hide(user(),"COACH",null,true).get("hiddenCount"));ledger.settle(user(),false,play,"MOCK");ledger.hide(user(),"COACH",null,true);ledger.hide(user(),"PLAY",null,true);assertTrue(ledger.services(user(),false).isEmpty());assertTrue(ledger.orders(user(),false).isEmpty());assertEquals(1,ledger.orders(admin(),true).size());assertEquals(2,((List<?>)ledger.bill(user(),false,play).get("services")).size());}
 @Test void estimatesAreClearlySeparateFromFinalMoneyAndProductionMockIsBlocked(){long play=open(user(),1);var coach=book(play,"coach-tangtang");var bill=ledger.bill(user(),false,play);assertEquals(new BigDecimal("0.00"),bill.get("unpaidAmount"));assertEquals(new BigDecimal("60.00"),bill.get("estimatedUnpaidAmount"));assertThrows(IllegalArgumentException.class,()->ledger.settle(user(),false,play,"MOCK"));b.finish(user(),false,play);Ledger target=org.springframework.test.util.AopTestUtils.getUltimateTargetObject(ledger);boolean previous=target.demo;try{target.demo=false;assertThrows(IllegalArgumentException.class,()->ledger.settle(user(),false,play,"MOCK"));assertThrows(IllegalArgumentException.class,()->ledger.settle(user(),false,play,"CASH"));ledger.settle(admin(),true,play,"CASH");assertEquals("CASH",b.row("select payment_method from service_order where id=?",id(coach)).get("payment_method"));}finally{target.demo=previous;}}
 @Test void concurrentBookingAndFinishingHaveOneConsistentOutcome()throws Exception{long play=open(user(),1);long iid=item("coach-tangtang"),uid=user();var pool=Executors.newFixedThreadPool(2);try{var gate=new CountDownLatch(1);var booking=pool.submit(()->{gate.await();try{return c.book(uid,false,iid,play,UUID.randomUUID().toString());}catch(IllegalArgumentException ended){return null;}});var ending=pool.submit(()->{gate.await();b.finish(uid,false,play);return true;});gate.countDown();ending.get(15,TimeUnit.SECONDS);var service=booking.get(15,TimeUnit.SECONDS);assertEquals(0,b.jdbc().queryForObject("select count(*) from service_order where play_order_id=? and status='ACTIVE'",Integer.class,play));if(service!=null)assertEquals("COMPLETED",b.row("select status from service_order where id=?",service.get("id")).get("status"));}finally{pool.shutdownNow();}}
 @Test void legacyUnlinkedServicesCanStillBeFinishedAndSettled(){long iid=item("coach-tangtang");b.jdbc().update("insert into service_order(request_key,user_id,item_id,item_name,kind,rate,status,created_at,started_at) values(?,?,?,'旧版助教','COACH',1,'ACTIVE',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",UUID.randomUUID().toString(),user(),iid);long sid=b.jdbc().queryForObject("select max(id) from service_order",Long.class);c.action(user(),false,sid,"finish");c.action(admin(),true,sid,"settle");ledger.hide(user(),"COACH",List.of(sid),false);assertTrue(ledger.services(user(),false).isEmpty());}
 @Test void onlyUnassignedFrontDeskSessionCanBeAssigned(){long play=id(b.open(admin(),true,1,1,UUID.randomUUID().toString(),"CASH"));assertThrows(IllegalArgumentException.class,()->ledger.assignCustomer(user(),false,play,user()));ledger.assignCustomer(admin(),true,play,user());assertEquals(user(),((Number)b.row("select user_id from play_order where id=?",play).get("user_id")).longValue());ledger.assignCustomer(admin(),true,play,user());assertThrows(IllegalArgumentException.class,()->ledger.assignCustomer(admin(),true,play,other()));assertEquals(1,ledger.orders(user(),false).size());book(play,"coach-tangtang");assertEquals(user(),((Number)b.row("select user_id from service_order where play_order_id=?",play).get("user_id")).longValue());long hasService=id(b.open(admin(),true,2,1,UUID.randomUUID().toString(),"CASH"));c.book(admin(),true,item("peri-tianwang"),hasService,UUID.randomUUID().toString());assertEquals(true,ledger.bill(admin(),true,hasService).get("canAssignCustomer"));ledger.assignCustomer(admin(),true,hasService,other());assertEquals(other(),((Number)b.row("select user_id from service_order where play_order_id=?",hasService).get("user_id")).longValue());long mini=open(other(),3);assertThrows(IllegalArgumentException.class,()->ledger.assignCustomer(admin(),true,mini,other()));}
 @Test void concurrentDuplicateRequestReturnsOneService()throws Exception{long play=open(user(),1),uid=user(),iid=item("coach-tangtang");String key=UUID.randomUUID().toString();var pool=Executors.newFixedThreadPool(4);try{var gate=new CountDownLatch(1);var jobs=new ArrayList<Future<Map<String,Object>>>();for(int n=0;n<4;n++)jobs.add(pool.submit(()->{gate.await();return c.book(uid,false,iid,play,key);}));gate.countDown();var ids=new HashSet<Long>();for(var job:jobs)ids.add(id(job.get(15,TimeUnit.SECONDS)));assertEquals(1,ids.size());assertEquals(1,b.jdbc().queryForObject("select count(*) from service_order",Integer.class));}finally{pool.shutdownNow();}}
 @Test void differentSessionsCompeteForOnePhysicalCue()throws Exception{long first=open(user(),1),second=open(other(),2),uid=user(),otherUid=other(),iid=item("peri-tianwang");var pool=Executors.newFixedThreadPool(2);try{var gate=new CountDownLatch(1);var jobs=new ArrayList<Future<Boolean>>();jobs.add(pool.submit(()->{gate.await();try{c.book(uid,false,iid,first,UUID.randomUUID().toString());return true;}catch(IllegalArgumentException busy){return false;}}));jobs.add(pool.submit(()->{gate.await();try{c.book(otherUid,false,iid,second,UUID.randomUUID().toString());return true;}catch(IllegalArgumentException busy){return false;}}));gate.countDown();int won=0;for(var job:jobs)if(job.get(15,TimeUnit.SECONDS))won++;assertEquals(1,won);assertEquals(1,b.jdbc().queryForObject("select count(*) from service_order where item_id=? and status='REQUESTED'",Integer.class,iid));}finally{pool.shutdownNow();}}
}

